#!/usr/bin/env python3
"""Generate dump_state.sail: print every register of a state file in the canonical format.

  gen-dump.py STATE SAIL_FILE...  > dump_state.sail

STATE: a Rocq state file (e.g. validation/build/dumps/addi/reset.state); its register
names are the set to dump. SAIL_FILE...: the model's sources, for the register types.
Types: bool, bit, bits(n) and bitfields (.bits), enums (constructor name), structs
(one item per field, recursively).
"""

import re
import sys

HEADER = """\
/* Generated by validation/emulator/gen-dump.py; do not edit. */

val dump_bits = impure {c: "dump_bits"} : forall 'n. (string, bits('n)) -> unit
val dump_bool = impure {c: "dump_bool"} : (string, bool) -> unit
val dump_word = impure {c: "dump_word"} : (string, string) -> unit
"""


def strip_comments(text):
    text = re.sub(r"/\*.*?\*/", " ", text, flags=re.S)
    return re.sub(r"//[^\n]*", " ", text)


def parse(paths):
    regs, enums, structs, bitfields, synonyms = {}, {}, {}, set(), {}
    for path in paths:
        text = strip_comments(open(path).read())
        for m in re.finditer(r"^\s*register\s+(\w+)\s*:\s*([\w']+(?:\([^)]*\))?)", text, re.M):
            regs.setdefault(m.group(1), m.group(2))
        for m in re.finditer(r"^\s*enum\s+(\w+)\s*=\s*\{([^}]*)\}", text, re.M):
            enums[m.group(1)] = [c.strip() for c in m.group(2).split(",") if c.strip()]
        for m in re.finditer(r"^\s*struct\s+(\w+)\s*=\s*\{([^}]*)\}", text, re.M):
            fields = re.findall(r"(\w+)\s*:\s*([^,]+?)\s*(?:,|$)", m.group(2).strip())
            structs[m.group(1)] = fields
        for m in re.finditer(r"^\s*bitfield\s+(\w+)\s*:", text, re.M):
            bitfields.add(m.group(1))
        for m in re.finditer(r"^\s*type\s+(\w+)\s*=\s*(\w+)\s*$", text, re.M):
            synonyms[m.group(1)] = m.group(2)
    return regs, enums, structs, bitfields, synonyms


def main(argv):
    if len(argv) < 2:
        print(__doc__, file=sys.stderr)
        return 2
    with open(argv[0]) as f:
        keys = [l.split(" ")[0] for l in f if not l.startswith(("mem ", "tag "))]
    names = list(dict.fromkeys(k.split(".")[0] for k in keys))
    regs, enums, structs, bitfields, synonyms = parse(argv[1:])

    def resolve(ty):
        while ty in synonyms:
            ty = synonyms[ty]
        return ty

    helpers = {}  # type -> Sail function text

    def item(key, expr, ty):
        """Sail statement printing EXPR of type TY under the key string expression KEY."""
        ty = resolve(ty)
        if ty == "bool":
            return f"dump_bool({key}, {expr})"
        if ty == "bit":
            return f"dump_bits({key}, [{expr}])"
        if ty in bitfields:
            return f"dump_bits({key}, {expr}.bits)"
        if ty in enums:
            if ty not in helpers:
                arms = ", ".join(f'{c} => "{c}"' for c in enums[ty])
                helpers[ty] = (f"function dump_{ty}(k : string, v : {ty}) -> unit =\n"
                               f"  dump_word(k, match v {{ {arms} }})\n")
            return f"dump_{ty}({key}, {expr})"
        if ty in structs:
            if ty not in helpers:
                helpers[ty] = None  # recursion guard
                body = ";\n  ".join(item(f'k ^ ".{f}"', f"v.{f}", t) for f, t in structs[ty])
                helpers[ty] = f"function dump_{ty}(k : string, v : {ty}) -> unit = {{\n  {body}\n}}\n"
            return f"dump_{ty}({key}, {expr})"
        if re.fullmatch(r"bits\(.*\)|xlenbits|\w*bits", ty):
            return f"dump_bits({key}, {expr})"
        raise SystemExit(f"gen-dump.py: no rendering for type {ty!r} ({expr})")

    stmts = []
    for name in names:
        if name not in regs:
            raise SystemExit(f"gen-dump.py: register {name} not declared in the Sail sources")
        stmts.append(item(f'"{name}"', name, regs[name]))

    out = [HEADER]
    out += [h for h in helpers.values()]
    out.append("val dump_state : unit -> unit\n"
               "function dump_state() = {\n  " + ";\n  ".join(stmts) + "\n}\n")
    sys.stdout.write("\n".join(out))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
